"""Крымскотатарский слой для разделов 2–9 (литературный язык, кириллица). ЧЕРНОВИК — проверка носителем."""
import re

NAMES = {'ا': 'Элиф', 'ب': 'Бе', 'ت': 'Те', 'ث': 'Се', 'ج': 'Джим', 'ح': 'Ха', 'خ': 'Хо', 'د': 'Даль', 'ذ': 'Зель', 'ر': 'Ра', 'ز': 'Зе',
         'س': 'Син', 'ش': 'Шин', 'ص': 'Сад', 'ض': 'Дад', 'ط': 'Та', 'ظ': 'За', 'ع': 'Айн', 'غ': 'Гъайн', 'ف': 'Фе', 'ق': 'Къаф', 'ك': 'Кяф',
         'ل': 'Лям', 'م': 'Мим', 'ن': 'Нун', 'ه': 'Хе', 'و': 'Вав', 'ي': 'Йе'}

# --- переопределение текстов движка огласовок / тенвина / медда
SETS_JS = r'''
(function(){
 const h = SETS.h, t = SETS.t, m = SETS.m;
 const HN = ['Фатха','Касра','Дамма'];
 HV[0].name='Фатха'; HV[1].name='Касра'; HV[2].name='Дамма';
 h.sec='Харекелер'; h.hat='Харекени'; h.hats='харекени';
 h.V[0].name='Фатха'; h.V[0].where='<b>устюнде</b> чызыкъчыкъ'; h.V[0].mouth='Агъызчыкъны кенъ ачамыз';
 h.V[1].name='Касра'; h.V[1].where='<b>тюбюнде</b> чызыкъчыкъ'; h.V[1].mouth='Дудакъларнынъ кенарлары кулюмсирей';
 h.V[2].name='Дамма'; h.V[2].where='<b>устюнде</b> кичкене ильмекчик'; h.V[2].mouth='Дудакълар боручыкъ киби топлана';
 ['Фатха','Касра','Дамма','Эпси бирликте'].forEach((x,i)=>h.lessons[i].title=x);
 h.greet = k => k===0 ? 'Арифлер тылсымлы башлыкълар кийелер! Биринджи башлыкъ — Фатха.' : k<3 ? `Биз ${HN[k-1]} башлыгъыны билемиз. Бугунь янъы башлыкъ — ${HN[k]}!` : 'Бугунь учь башлыкъны бирликте топлап, чыгъырыкъны айландырырмыз!';
 h.baseText='Бу — Бе арифи. Озю тек «б» дей. Онъа башлыкъ кийдирейик!'; h.btn='Башлыкъ кийдир';
 h.note = v => `${v.mouth}. Къыскъа окъуймыз, бир хареке: «б${v.v}», «б${v.v}-${v.v}-${v.v}» дегиль.`;
 h.readHint='Онъдан солгъа, къыскъа ве ачыкъ окъуймыз. Эджагъа бас — о сычрар!'; h.threeTitle='Учь тылсымлы башлыкъ'; h.wheelTitle='Хареке чыгъырыгъы';
 const TN = ['Фатхатан','Касратан','Дамматан'];
 t.sec='Тенвин'; t.hat='Тенвинни'; t.hats='тенвинни';
 TN.forEach((x,i)=>t.V[i].name=x);
 t.V[0].where='<b>устюнде</b> эки чызыкъчыкъ ве сонъунда элиф'; t.V[0].mouth='Девам этип окъугъанда тенвинден сонъки элиф окъулмай';
 t.V[1].where='<b>тюбюнде</b> эки чызыкъчыкъ'; t.V[1].mouth='Кулюмсиреймиз ве «н» къошамыз';
 t.V[2].where='<b>устюнде</b> чифт ильмекчик'; t.V[2].mouth='Дудакълар боручыкъ ве «н» къошамыз';
 [...TN,'Эпси бирликте'].forEach((x,i)=>t.lessons[i].title=x);
 t.greet = k => k===0 ? 'Башлыкъ эки олса не ола? «Н» акс-садасы пейда ола! Бу — тенвин.' : k<3 ? `Биз ${TN[k-1]}ни билемиз. Бугунь — ${TN[k]}!` : 'Бугунь учь тенвинни бирликте топлап, чыгъырыкъны айландырырмыз!';
 t.baseText='Бу эджада бир башлыкъ бар. Эгер эки олса?'; t.btn='Башлыкъны экилештир';
 t.note = v => `${v.mouth}. Тенвин — акс-сада киби: «б${v.v}-н».`;
 t.readHint='Онъдан солгъа окъуймыз: эр эджанынъ сонъунда енгиль «н» эшитиле.'; t.threeTitle='Учь тенвин'; t.wheelTitle='Тенвин чыгъырыгъы';
 const MN = ['Элифнен медд','Йенен медд','Вавнен медд'];
 m.sec='Медд'; m.hat='Меддни'; m.hats='меддни';
 MN.forEach((x,i)=>m.V[i].name=x);
 m.V[0].where='фатха, ондан сонъ <b>элиф</b>'; m.V[0].mouth='«а»ны 2 хареке узатамыз — эки адым';
 m.V[1].where='касра, ондан сонъ <b>йе</b>'; m.V[1].mouth='«и»ни 2 хареке узатамыз — эки адым';
 m.V[2].where='дамма, ондан сонъ <b>вав</b>'; m.V[2].mouth='«у»ны 2 хареке узатамыз — эки адым';
 ['Элифнен','Йенен','Вавнен','Эпси бирликте'].forEach((x,i)=>m.lessons[i].title=x);
 m.greet = k => k===0 ? 'Сеслер къыскъа ве узун ола! Бугунь «а» сесини узатмагъа огренемиз.' : k<3 ? `Биз «${['а','и'][k-1]}» сесини узатмагъа билемиз. Бугунь «${['','и','у'][k]}» узатамыз!` : 'Бугунь бутюн узун сеслерни бирликте топлаймыз!';
 m.baseText='Бу къыскъа эджа — бир адым. Ондан сонъ медд арифи турса?'; m.btn='Медд арифини къош';
 m.note = v => `${v.mouth}: «б${v.v}». Къыскъа сес — бир адым, узун — эки адым!`;
 m.readHint='Онъдан солгъа окъуймыз ве эр сесни тамам 2 хареке узатамыз.'; m.threeTitle='Учь узун сес'; m.wheelTitle='Медд чыгъырыгъы';
 SKL[0].t='Сукун'; SKL[1].t='Шедде';
})();
'''

